import datetime

class ValidatorMeta(type):
    def __new__(mcs, name, bases, namespace):
        if not name[0].isupper():
            raise ValueError(f"类名 '{name}' 必须以大写字母开头")
        namespace['created_at'] = str(datetime.datetime.now())
        return super().__new__(mcs, name, bases, namespace)

# 正常创建的类
class GoodClass(metaclass=ValidatorMeta):
    pass

print(f"类 {GoodClass.__name__} 创建成功，created_at = {GoodClass.created_at}")

